import * as React from 'react';
import * as AutoGridPrimitive from '@exhuma/core';
import { cn } from '@/lib/utils';

export interface AutoGridProps extends React.ComponentPropsWithoutRef<typeof AutoGridPrimitive.AutoGrid> {
  className?: string;
}

export const AutoGrid = React.forwardRef<HTMLDivElement, AutoGridProps>(
  ({ className, children, ...props }, ref) => (
    <AutoGridPrimitive.AutoGrid
      ref={ref}
      className={cn(
        'grid grid-cols-[repeat(auto-fill,minmax(min(100%,280px),1fr))] gap-6 w-full',
        className
      )}
      {...props}
    >
      {children}
    </AutoGridPrimitive.AutoGrid>
  )
);
AutoGrid.displayName = 'AutoGrid';

