import { AutoGrid } from '@exhuma/core';

class ExhumaAutoGridElement extends HTMLElement {
  connectedCallback() {
    this.classList.add('exhuma-auto-grid');
    this.style.display = 'block';
  }
}

if (!customElements.get('exhuma-auto-grid')) {
  customElements.define('exhuma-auto-grid', ExhumaAutoGridElement);
}

react-native.code:
import React from 'react';
import { View, StyleSheet, type ViewProps } from 'react-native';
import * as AutoGridPrimitive from '@exhuma/core';

export interface AutoGridProps extends ViewProps {
  children?: React.ReactNode;
}

export function AutoGrid({ style, children, ...props }: AutoGridProps) {
  return (
    <View style={[styles.container, style]} {...props}>
      {children}
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    borderRadius: 16,
    borderWidth: 1,
    borderColor: '#e2e8f0',
    backgroundColor: '#ffffff',
    padding: 20,
    overflow: 'hidden',
  },
});

